def MC(n,left,k,expl):
    R={"A":"A 但是很好吃。","B":"B 但不是双胞胎。","C":"C 但是太累了。","D":"D 但是我也要去跑步。","E":"E 但是很有意思。"}
    return _mk(n,left+"（选后半句）",list(R.values()),R[k],expl,f"m{n}")
